      "summary": "\ufeff---\ntitle: \"Agentic Execution Graphs & Autonomous Routines\"\ndomain: \"ai-and-intelligent-systems\"\ncategory: \"general\"\ntype: \"concept\"\ntags: \"ai\", \"agents\", \"execution-graphs\", \"claude-code\", \"routines...",
      "tags": [],
