      "filename": "karpathy-llm-wiki-method.md",
      "relPath": "knowledge/general/ai-and-intelligent-systems/karpathy-llm-wiki-method.md",
      "path": "knowledge/general/ai-and-intelligent-systems/karpathy-llm-wiki-method.md",
