      "created": "2026-08-19",
      "updated": "2026-08-19",
      "summary": "\ufeff---\ntitle: \"Andrej Karpathy's LLM Wiki & Second Brain Method\"\ndomain: \"ai-and-intelligent-systems\"\ncategory: \"general\"\ntype: \"concept\"\ntags: \"ai\", \"second-brain\", \"llm-wiki\", \"karpathy\", \"knowledge-m...",
      "tags": [],
