      "title": "BA Insight Configuration, Operations & Troubleshooting",
      "category": "work",
      "categoryName": "Work",
      "domain": "ba-insight",
      "topic": "BA Insight Platform",
      "topicName": "BA Insight Platform",
      "type": "note",
