      "summary": "\ufeff---\ntitle: \"BA Insight REST API Reference & Services\"\ndomain: \"ba-insight\"\ncategory: \"work\"\ntype: \"reference\"\ntags: \"ba-insight\", \"api\", \"rest-api\", \"search-service\", \"nlq\", \"analytics\", \"developer\"\n...",
      "tags": [],
