      "summary": "\ufeff---\ntitle: \"Golden Prompts\"\ndomain: \"prompt-engineering\"\ncategory: \"prompt-engineering\"\ntype: \"reference\"\ntags: \"golden-prompts\", \"templates\", \"validated\", \"prompt-engineering\"\ncreated: 2026-08-17\nup...",
      "tags": [],
