      "summary": "\ufeff---\ntitle: \"Hit-Highlighting & In-Document Navigation\"\ndomain: \"smartpreviews\"\ncategory: \"work\"\ntype: \"guide\"\ntags: \"smartpreviews\", \"hit-highlighting\", \"navigation\", \"bounding-boxes\"\ncreated: 2026-0...",
      "tags": [],
