      "summary": "\ufeff---\ntitle: \"Prompt Conventions\"\ndomain: \"prompt-engineering\"\ncategory: \"prompt-engineering\"\ntype: \"concept\"\ntags: \"conventions\", \"rules\", \"constraints\", \"prompt-engineering\", \"validated\"\ncreated: 202...",
      "tags": [],
