      "summary": "\ufeff---\ntitle: \"SharePoint & Microsoft Teams Preview Integration\"\ndomain: \"smartpreviews\"\ncategory: \"work\"\ntype: \"guide\"\ntags: \"smartpreviews\", \"sharepoint\", \"teams\", \"integration\"\ncreated: 2026-08-18\nup...",
      "tags": [],
