      "summary": "\ufeff---\ntitle: \"SmartHub API Reference\"\ndomain: \"work-projects\"\ncategory: \"projects\"\ntype: \"reference\"\ntags: \"api\", \"rest\", \"authentication\", \"search\", \"conversational-search\", \"smarthub\"\ncreated: 2026-0...",
