      "summary": "\ufeff---\ntitle: \"SmartHub Content Containers Module\"\ndomain: \"smarthub\"\ncategory: \"work\"\ntype: \"reference\"\ntags: \"smarthub\", \"content-containers\", \"cbs\", \"ui-builder\", \"result-rendering\"\ncreated: 2026-08-...",
