      "summary": "\ufeff---\ntitle: \"SmartHub Conversational Search & Agentic RAG Architecture\"\ndomain: \"work-projects\"\ncategory: \"projects\"\ntype: \"spec\"\ntags: \"ai\", \"conversational-search\", \"agentic-rag\", \"llm\", \"streaming\"...",
      "tags": [],
