      "summary": "\ufeff---\ntitle: \"SmartHub Conversational Search & RAG\"\ndomain: \"smarthub\"\ncategory: \"work\"\ntype: \"spec\"\ntags: \"smarthub\", \"conversational-search\", \"rag\", \"llm\", \"chatbot\", \"vector-search\", \"sse\"\ncreated: ...",
