      "summary": "\ufeff---\ntitle: \"SmartHub Inbound Web-API CSRF Hardening\"\ndomain: \"smarthub\"\ncategory: \"work\"\ntype: \"guide\"\ntags: \"smarthub\", \"security\", \"csrf\", \"web-api\", \"cookies\", \"cors\", \"authentication\"\ncreated: 20...",
