      "id": "knowledge__work__smarthub__search-engine-connectors",
      "filename": "search-engine-connectors.md",
      "relPath": "knowledge/work/smarthub/search-engine-connectors.md",
      "path": "knowledge/work/smarthub/search-engine-connectors.md",
      "title": "SmartHub Search Engine Bindings",
      "category": "work",
