      "summary": "\ufeff---\ntitle: \"SmartHub SearchUI Module Architecture \u2014 Detailed Reference\"\ndomain: \"work-projects\"\ncategory: \"projects\"\ntype: \"reference\"\ntags: \"smarthub\", \"searchui\", \"modules\", \"architecture\", \"javasc...",
