      "summary": "\ufeff---\ntitle: \"SmartHub Ticket History \u2014 Implemented Designs, Fixes & Retrospectives\"\ndomain: \"work-projects\"\ncategory: \"projects\"\ntype: \"reference\"\ntags: \"smarthub\", \"ticket-history\", \"decisions\", \"ret...",
      "tags": [],
