      "summary": "\ufeff---\ntitle: \"SmartHub UI/UX Dark Mode & Performance Optimization Guide\"\ndomain: \"work-projects\"\ncategory: \"projects\"\ntype: \"spec\"\ntags: \"smarthub\", \"dark-mode\", \"responsive-design\", \"performance\", \"co...",
