      "summary": "\ufeff---\ntitle: \"SmartHub Roadmap\"\ndomain: \"work-projects\"\ncategory: \"projects\"\ntype: \"spec\"\ntags: \"roadmap\", \"milestones\", \"smarthub\", \"federated-search\"\ncreated: 2026-08-17\nupdated: 2026-08-17\nstatus: a...",
      "tags": [],
