      "summary": "\ufeff---\ntitle: \"SmartPreviews Knowledge Domain Index\"\ndomain: \"smartpreviews\"\ncategory: \"work\"\ntype: \"hub\"\ntags: \"smartpreviews\", \"index\", \"moc\"\ncreated: 2026-08-18\nupdated: 2026-08-18\nstatus: active\nsum...",
      "tags": [],
