      "summary": "\ufeff---\ntitle: \"Source System Definitions & Configuration\"\ndomain: \"connectivity-hub\"\ncategory: \"work\"\ntype: \"guide\"\ntags: \"connectivity-hub\", \"configuration\", \"source-systems\", \"authentication\"\ncreated:...",
      "tags": [],
