      "summary": "\ufeff---\ntitle: \"Taxonomy Management & Classification Rules\"\ndomain: \"autoclassifier\"\ncategory: \"work\"\ntype: \"guide\"\ntags: \"autoclassifier\", \"taxonomy\", \"classification\", \"rules\"\ncreated: 2026-08-18\nupdat...",
      "tags": [],
