      "id": "knowledge__general__ai-and-intelligent-systems__vibe-coding-2-0",
      "filename": "vibe-coding-2-0.md",
      "relPath": "knowledge/general/ai-and-intelligent-systems/vibe-coding-2-0.md",
      "path": "knowledge/general/ai-and-intelligent-systems/vibe-coding-2-0.md",
      "title": "Vibe Coding 2.0",
      "category": "general",
      "categoryName": "General",
      "domain": "ai-and-intelligent-systems",
